module TopModule(
    input clk,
    input [7:0] in,
    output [7:0] anyedge
);

// Define a register to store the previous input value
reg [7:0] prev_in;

// Define a register to store the output value
reg [7:0] anyedge;

// Define a counter to keep track of the number of clock cycles
// since the last edge detection
reg [31:0] counter;

// Define a reset signal to reset the counter
reg reset;

// Define a combinational logic to detect any edge
always @(posedge clk) begin
    // Reset the counter if the reset signal is asserted
    if (reset) begin
        counter <= 0;
    end

    // Increment the counter if the input value has changed
    // from the previous clock cycle
    if (in !== prev_in) begin
        counter <= counter + 1;
    end

    // Set the output bit to 1 if the counter has reached
    // the desired value
    if (counter == 2) begin
        anyedge <= 1;
    end

    // Reset the output bit if the input value has changed
    // from the previous clock cycle
    if (in !== prev_in) begin
        anyedge <= 0;
    end
end

// Define a sequential logic to store the previous input value
always @(posedge clk) begin
    prev_in <= in;
end

// Define a reset logic to reset the counter and the output bit
always @(posedge clk) begin
    if (reset) begin
        counter <= 0;
        anyedge <= 0;
    end
end

endmodule

