            if (in == 0) begin
                next_state = 4'b0001;
                out = 0;
            end else begin
                next_state = 4'b0010;
                out = 0;
            end
        end
        4'b0010: begin // B
            if (in == 0) begin
                next_state = 4'b0010;
                out = 0;
            end else begin
                next_state = 4'b0100;
                out = 0;
            end
        end
        4'b0100: begin // C
