                next_state = 4'b0010;
                out = 0;
            end else begin
                next_state = 4'b1000;
                out = 1;
            end
        end
        4'b1000: begin // D
            if (in == 0) begin
                next_state = 4'b0100;
                out = 0;
            end else begin
                next_state = 4'b0010;
                out = 0;
            end
        end
    endcase
end

