module TopModule(
    input clk,
    input reset,
    output [31:0] q
);

// Define the Galois LFSR parameters
localparam TAPS = 4;
localparam TAP_POS = {32, 22, 2, 1};

// Define the shift register
reg [31:0] shift_reg = 32'h1;

// Define the XOR gates
wire [31:0] xor_out;

// Implement the Galois LFSR
always @(posedge clk) begin
    if (reset) begin
        shift_reg <= 32'h1;
    end else begin
        shift_reg <= {shift_reg[30:0], xor_out[31]};
    end
end

// Implement the XOR gates
always @(*) begin
    xor_out = shift_reg;
    for (int i = 0; i < TAPS; i++) begin
        xor_out[TAP_POS[i]] = shift_reg[TAP_POS[i]] ^ shift_reg[0];
    end
end

// Assign the output
assign q = shift_reg;

endmodule

