module TopModule(
    input clk,
    input reset,
    output [4:0] q
);

// Define the taps for the Galois LFSR
localparam [3:0] taps = 5'b1001;

// Define the initial state of the LFSR
localparam [4:0] init_state = 5'b00001;

// Define the register to store the current state of the LFSR
reg [4:0] state;

// Define the output of the LFSR
wire [4:0] q;

// Define the XOR gates for the Galois LFSR
wire [4:0] xor_out;

// Define the shift register
reg [4:0] shift_reg;

// Define the counter for the number of clock cycles
reg [3:0] counter;

// Define the reset signal
reg reset_signal;

// Define the active-high synchronous reset
always @(posedge clk)
begin
    if (reset)
    begin
        // Reset the LFSR output to 1
        q <= 5'b00001;
        // Reset the counter to 0
        counter <= 4'b0000;
        // Reset the shift register to 0
        shift_reg <= 5'b00000;
        // Reset the state to the initial state
        state <= init_state;
        // Reset the reset signal to 0
        reset_signal <= 0;
    end
    else
    begin
        // Increment the counter
        counter <= counter + 1;
        // Shift the shift register to the right
        shift_reg <= shift_reg >> 1;
        // XOR the taps with the LSB output bit
        xor_out <= taps ^ shift_reg[0];
        // Shift the state to the right
        state <= state >> 1;
        // XOR the XOR output with the LSB output bit
        q <= xor_out ^ state[0];
        // Set the reset signal to 1
        reset_signal <= 1;
    end
end

endmodule

