    if (areset) begin
        state <= 2'b00;
    end else begin
        case (state)
            2'b00: begin
                if (x == 1'b0) begin
                    state <= 2'b00;
                end else begin
                    state <= 2'b01;
                end
            end
            2'b01: begin
                if (x == 1'b0) begin
                    state <= 2'b01;
                end else begin
                    state <= 2'b10;
                end
            end
            2'b10: begin
                if (x == 1'b0) begin
                    state <= 2'b10;
                end else begin
                    state <= 2'b11;
                end
            end
            2'b11: begin
                if (x == 1'b0) begin
                    state <= 2'b11;
                end else begin
                    state <= 2'b00;
                end
            end
        endcase
    end
end

// Define the output logic
always @(posedge clk) begin
    case (state)
        2'b00: begin
            z <= 1'b0;
        end
        2'b01: begin
            z <= 1'b1;
        end
        2'b10: begin
            z <= 1'b1;
        end
        2'b11: begin
            z <= 1'b0;
        end
    endcase
end

