module TopModule(
    input clk,
    input reset,
    input data,
    output reg start_shifting
);

// Define the finite-state machine states
typedef enum int {
    IDLE,
    SEARCHING,
    FOUND
} state_t;

// Define the state variable
state_t state;

// Define the output signal
reg start_shifting;

// Define the input signal
wire data;

// Define the clock signal
wire clk;

// Define the reset signal
wire reset;

// Define the state transition logic
always @(posedge clk) begin
    if (reset) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: begin
                if (data == 1'b1) begin
                    state <= SEARCHING;
                end
            end
            SEARCHING: begin
                if (data == 1'b1) begin
                    state <= SEARCHING;
                end else begin
                    state <= FOUND;
                end
            end
            FOUND: begin
                start_shifting <= 1'b1;
                state <= FOUND;
            end
        endcase
    end
end

// Define the output logic
always @(posedge clk) begin
    if (reset) begin
        start_shifting <= 1'b0;
    end else begin
        if (state == FOUND) begin
            start_shifting <= 1'b1;
        end
    end
end

endmodule

