localparam A = 0;
localparam B = 1;
localparam C = 2;
localparam D = 3;
localparam E = 4;
localparam F = 5;

// Define the next-state signals
wire Y2;
wire Y4;

// Define the state register
reg [5:0] y_reg;

// Define the next-state logic
always @(posedge w) begin
    case (y_reg)
        A: begin
            Y1 = 0;
            Y3 = 0;
            if (y == 0) begin
                y_reg = B;
            end else begin
                y_reg = A;
            end
        end
        B: begin
            Y1 = 0;
            Y3 = 0;
            if (y == 0) begin
                y_reg = A;
            end else begin
