            Y1 = 0;
            Y3 = 0;
            if (y == 0) begin
                y_reg = D;
            end else begin
                y_reg = C;
            end
        end
        D: begin
            Y1 = 0;
            Y3 = 0;
            if (y == 0) begin
                y_reg = C;
            end else begin
                y_reg = D;
            end
        end
        E: begin
            Y1 = 1;
            Y3 = 1;
            if (y == 0) begin
                y_reg = E;
            end else begin
                y_reg = D;
            end
        end
        F: begin
            Y1 = 1;
            Y3 = 1;
            if (y == 0) begin
                y_reg = D;
            end else begin
