typedef enum int {
    B,
    A
} state_t;

// Define the state register
state_t state;

// Define the output register
reg out_reg;

// Define the input register
reg in_reg;

// Define the next state function
function next_state(state_t state, input in);
    case (state)
        B: begin
            if (in == 0) begin
                next_state = B;
            end
            else begin
                next_state = A;
            end
        end
        A: begin
            if (in == 0) begin
                next_state = B;
            end
            else begin
                next_state = A;
            end
        end
    endcase
endfunction

// Define the output function
function out_func(state_t state);
    case (state)
        B: begin
            out_func = 1;
        end
        A: begin
            out_func = 0;
        end
    endcase
endfunction

// Define the clock edge sensitivity
always @(posedge clk) begin
    // Reset the state and output registers
    if (reset == 1) begin
        state = B;
        out_reg = 1;
        in_reg = 0;
    end
    // Update the state and output registers
    else begin
        state = next_state(state, in_reg);
        out_reg = out_func(state);
    end
end

// Define the output port
assign out = out_reg;

