module TopModule(
    input clk,
    input in,
    input reset,
    output reg [7:0] out_byte,
    output reg done
);

// Define the states of the finite state machine
typedef enum {
    IDLE,
    START_BIT,
    DATA_BITS,
    STOP_BIT
} state_t;

// Define the state variables
state_t current_state, next_state;
reg [7:0] data_bits;
reg stop_bit;

// Define the output signals
reg [7:0] out_byte;
reg done;

// Define the state transition logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= IDLE;
        data_bits <= 0;
        stop_bit <= 0;
        out_byte <= 0;
        done <= 0;
    end else begin
        current_state <= next_state;
        data_bits <= data_bits;
        stop_bit <= stop_bit;
        out_byte <= out_byte;
        done <= done;
    end
end

// Define the state machine logic
always @(*) begin
    case (current_state)
        IDLE: begin
            if (in) begin
                next_state <= START_BIT;
            end else begin
                next_state <= IDLE;
            end
        end
        START_BIT: begin
            if (in) begin
                next_state <= DATA_BITS;
            end else begin
                next_state <= START_BIT;
            end
        end
        DATA_BITS: begin
            if (in) begin
                data_bits[0] <= in;
                next_state <= DATA_BITS;
            end else begin
                next_state <= STOP_BIT;
            end
        end
        STOP_BIT: begin
            if (in) begin
                stop_bit <= 1;
                next_state <= STOP_BIT;
            end else begin
                next_state <= IDLE;
            end
        end
    endcase
end

// Define the output logic
always @(*) begin
    case (current_state)
        IDLE: begin
            out_byte <= 0;
            done <= 0;
        end
        START_BIT: begin
            out_byte <= 0;
            done <= 0;
        end
        DATA_BITS: begin
            out_byte <= data_bits;
            done <= 0;
        end
        STOP_BIT: begin
            out_byte <= data_bits;
            done <= 1;
        end
    endcase
end

endmodule

