module TopModule(
    input clk,
    input resetn,
    input r0,
    input r1,
    input r2,
    output g0,
    output g1,
    output g2
);

// State codes
localparam A = 3'b000;
localparam B = 3'b001;
localparam C = 3'b010;
localparam D = 3'b100;

// State flip-flops
reg [2:0] state;

// State table
always @(posedge clk) begin
    if (!resetn) begin
        state <= A;
    end else begin
        case (state)
            A: begin
                if (r0) begin
                    state <= B;
                end else if (r1) begin
                    state <= C;
                end else if (r2) begin
                    state <= D;
                end
            end
            B: begin
                if (r0) begin
                    state <= B;
                end else begin
                    state <= A;
                end
            end
            C: begin
                if (r1) begin
                    state <= C;
                end else begin
                    state <= A;
                end
            end
            D: begin
                if (r2) begin
                    state <= D;
                end else begin
                    state <= A;
                end
            end
        endcase
    end
end

// State outputs
always @(posedge clk) begin
    case (state)
        A: begin
            g0 <= 1;
            g1 <= 0;
            g2 <= 0;
        end
        B: begin
            g0 <= 1;
            g1 <= 0;
            g2 <= 0;
        end
        C: begin
            g0 <= 0;
            g1 <= 1;
            g2 <= 0;
        end
        D: begin
            g0 <= 0;
            g1 <= 0;
            g2 <= 1;
        end
    endcase
end

endmodule

module TopModule(
    input clk,
    input reset,
    input [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

// Define the state machine
typedef enum {
    IDLE,
    ABOVE_S2,
    BETWEEN_S2_S1,
    BETWEEN_S1_S0,
    BELOW_S0
} state_t;

state_t state;

// Define the nominal flow rate inputs
reg [2:0] nominal_flow_rate_inputs;

// Define the active-high synchronous reset
reg reset_active;

// Define the state machine next state logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= IDLE;
        reset_active <= 1'b1;
    end else begin
        if (reset_active) begin
            state <= IDLE;
            reset_active <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (s[2]) begin
                        state <= ABOVE_S2;
                    end else begin
                        state <= BETWEEN_S2_S1;
                    end
                end
                ABOVE_S2: begin
                    if (s[1]) begin
                        state <= BETWEEN_S2_S1;
                    end else begin
                        state <= BETWEEN_S1_S0;
                    end
                end
                BETWEEN_S2_S1: begin
                    if (s[0]) begin
                        state <= BETWEEN_S1_S0;
                    end else begin
                        state <= BELOW_S0;
                    end
                end
                BETWEEN_S1_S0: begin
                    if (s[0]) begin
                        state <= BELOW_S0;
                    end else begin
                        state <= BELOW_S0;
                    end
                end
                BELOW_S0: begin
                    if (s[0]) begin
                        state <= BELOW_S0;
                    end else begin
                        state <= BETWEEN_S2_S1;
                    end
                end
            endcase
        end
    end
end

// Define the state machine output logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b0;
        dfr <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
            ABOVE_S2: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
            BETWEEN_S2_S1: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            BETWEEN_S1_S0: begin
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
            BELOW_S0: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b1;
            end
        endcase
    end
end

// Define the nominal flow rate inputs logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        nominal_flow_rate_inputs <= 3'b000;
    end else begin
        if (state == BETWEEN_S2_S1) begin
            nominal_flow_rate_inputs <= 3'b001;
        end else if (state == BETWEEN_S1_S0) begin
            nominal_flow_rate_inputs <= 3'b010;
        end else begin
            nominal_flow_rate_inputs <= 3'b000;
        end
    end
end

// Define the flow rate logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b0;
    end else begin
        if (state == BETWEEN_S2_S1) begin
            fr2 <= nominal_flow_rate_inputs[2];
            fr1 <= nominal_flow_rate_inputs[1];
            fr0 <= nominal_flow_rate_inputs[0];
        end else if (state == BETWEEN_S1_S0) begin
            fr2 <= nominal_flow_rate_inputs[2];
            fr1 <= nominal_flow_rate_inputs[1];
            fr0 <= nominal_flow_rate_inputs[0];
        end else if (state == BELOW_S0) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
        end else begin
            fr2 <= 1'b0;
            fr1 <= 1'b0;
            fr0 <= 1'b0;
        end
    end
end

// Define the Supplemental flow rate logic
always @(posedge clk or posedge reset) begin
    if (reset) begin
        dfr <= 1'b0;
    end else begin
        if (state == BETWEEN_S2_S1) begin
            dfr <= 1'b0;
        end else if (state == BETWEEN_S1_S0) begin
            dfr <= 1'b1;
        end else begin
            dfr <= 1'b0;
        end
    end
end

endmodule

