    Count_next = (state == 10'b0000000100);
    Wait_next = (state == 10'b0000001000);
    done = (state == 10'b0000010000);
    counting = (state == 10'b0000100000);
    shift_ena = (state == 10'b0001000000);
end

// Next state logic
always @(*) begin
    next_state = state;
    case (state)
        10'b0000000001: next_state = (d == 1'b0) ? 10'b0000000010 : 10'b0000000001;
        10'b0000000010: next_state = (d == 1'b0) ? 10'b0000000100 : 10'b0000000010;
        10'b0000000100: next_state = (d == 1'b0) ? 10'b0000001000 : 10'b0000000100;
        10'b0000001000: next_state = (d == 1'b0) ? 10'b0000010000 : 10'b0000001000;
        10'b0000010000: next_state = (d == 1'b0) ? 10'b0000100000 : 10'b0000010000;
        10'b0000100000: next_state = (d == 1'b0) ? 10'b0001000000 : 10'b0000100000;
        10'b0001000000: next_state = (d == 1'b0) ? 10'b0010000000 : 10'b0001000000;
        10'b0010000000: next_state = (d == 1'b0) ? 10'b0100000000 : 10'b0010000000;
        10'b0100000000: next_state = (d == 1'b0) ? 10'b1000000000 : 10'b0100000000;
        10'b1000000000: next_state = (d == 1'b0) ? 10'b0000000001 : 10'b1000000000;
    endcase
end

